@pytest.mark.parametrize("path,obsolete_clause", CASES)
def test_active_consumers_do_not_restore_identity_exclusion_or_broken_fallback(path, obsolete_clause):
    text = " ".join((ROOT / path).read_text().split())
    assert obsolete_clause not in text, path + ": " + obsolete_clause
